import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './Register.css';

const Register = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [msg, setMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    identificacion: '',
    nombre: '',
    apellido: '',
    correo: '',
    ciudad: '',
    direccion: '',
    pais: '',
    contraseña: '',
    confirmarContraseña: '',
    rol: '',
    especialidad: '',
    biografia: '',
    historia: '',
    aceptarTerminos: false
  });

  const totalSteps = 5;
  const stepTitles = [
    'Tipo de Usuario',
    'Información Personal', 
    'Detalles Adicionales',
    'Seguridad',
    'Confirmación'
  ];

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
    setMsg(''); // Limpiar mensajes de error al cambiar
  };

  const selectUserType = (type) => {
    setForm(prev => ({ ...prev, rol: type }));
    setMsg('');
  };

  const canProceed = () => {
    switch (currentStep) {
      case 1:
        return form.rol !== '';
      case 2:
        return form.identificacion && form.nombre && form.apellido && 
               form.correo && form.ciudad;
      case 3:
        if (form.rol === 'artesano') {
          return form.especialidad && form.biografia;
        }
        return true;
      case 4:
        return form.contraseña && form.confirmarContraseña && 
               form.contraseña === form.confirmarContraseña;
      case 5:
        return form.aceptarTerminos;
      default:
        return false;
    }
  };

  const nextStep = () => {
    if (!canProceed()) return;

    if (currentStep === totalSteps) {
      handleSubmit();
      return;
    }

    setCurrentStep(prev => prev + 1);
  };

  const prevStep = () => {
    if (currentStep === 1) return;
    setCurrentStep(prev => prev - 1);
  };

  const handleSubmit = async () => {
    if (!form.aceptarTerminos) {
      setMsg('Debes aceptar los términos y condiciones.');
      return;
    }

    if (form.contraseña !== form.confirmarContraseña) {
      setMsg('Las contraseñas no coinciden.');
      return;
    }

    if (!form.identificacion) {
      setMsg('La identificación es obligatoria.');
      return;
    }

    const identificacionRegex = /^\d{8,15}$/;
    if (!identificacionRegex.test(form.identificacion)) {
      setMsg('La identificación debe contener solo números (8-15 dígitos).');
      return;
    }

    setLoading(true);
    setMsg('');

    try {
      const userData = {
        identificacion: form.identificacion,
        nombre: form.nombre,
        apellido: form.apellido,
        correo: form.correo,
        direccion: form.direccion,
        pais: form.pais,
        contraseña: form.contraseña,
        rol: form.rol
      };

      if (form.rol === 'artesano') {
        userData.especialidad = form.especialidad;
        userData.biografia = form.biografia;
        userData.historia = form.historia;
      }

      const response = await axios.post('http://localhost:3000/api/auth/register', userData);
      
      if (response.data.success) {
        alert('¡Cuenta creada exitosamente! Redirigiendo al login...');
        navigate('/login');
      }
    } catch (error) {
      console.error('Error en registro:', error);
      if (error.response && error.response.data && error.response.data.message) {
        setMsg(error.response.data.message);
      } else {
        setMsg('Error al crear la cuenta. Por favor intenta nuevamente.');
      }
    } finally {
      setLoading(false);
    }
  };

  const updateSummary = () => {
    return (
      <div className="summary">
        <h4 className="summary-title">Resumen de tu cuenta:</h4>
        <div className="summary-content">
          <div className="summary-item">
            <span className="summary-label">Tipo:</span> 
            {form.rol === 'comprador' ? 'Comprador' : 'Artesano'}
          </div>
          <div className="summary-item">
            <span className="summary-label">Identificación:</span> 
            {form.identificacion}
          </div>
          <div className="summary-item">
            <span className="summary-label">Nombre:</span> 
            {form.nombre} {form.apellido}
          </div>
          <div className="summary-item">
            <span className="summary-label">Email:</span> 
            {form.correo}
          </div>
          <div className="summary-item">
            <span className="summary-label">Ciudad:</span> 
            {form.ciudad}
          </div>
          {form.rol === 'artesano' && (
            <div className="summary-item">
              <span className="summary-label">Especialidad:</span> 
              {form.especialidad}
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="register-page">
      <div className="main-container">
        <div className="unified-container">
          {/* Left Column */}
          <div className="left-column">
            <div className="decorative-patterns">
              <div className="pattern-circle-1"></div>
              <div className="pattern-circle-2"></div>
              <div className="pattern-circle-3"></div>
              <div className="pattern-square"></div>
            </div>

            <div className="info-content">
              <div className="welcome-header">
                <div className="welcome-icon">👋</div>
                <h2 className="welcome-title">¡Únete a<br/>Artisa!</h2>
              </div>

              <p className="welcome-description">
                Estás a solo unos pasos de formar parte de nuestra comunidad artesanal.
              </p>

              {/* Progress */}
              <div className="progress-section">
                <div className="progress-header">
                  <span className="progress-step">Paso {currentStep} de {totalSteps}</span>
                  <span className="progress-percentage">{Math.round((currentStep / totalSteps) * 100)}%</span>
                </div>
                <div className="progress-bar">
                  <div 
                    className="progress-fill" 
                    style={{ width: `${(currentStep / totalSteps) * 100}%` }}
                  ></div>
                </div>
                <p className="progress-title">{stepTitles[currentStep - 1]}</p>
              </div>

              {/* Steps */}
              <div className="steps-list">
                {[1, 2, 3, 4, 5].map(step => (
                  <div key={step} className="step-item">
                    <div className={`step-number ${
                      step < currentStep ? 'step-completed' : 
                      step === currentStep ? 'step-current' : 'step-pending'
                    }`}>
                      {step < currentStep ? '✓' : step}
                    </div>
                    <span className={`step-text ${
                      step === currentStep ? 'step-text-current' : 'step-text-normal'
                    }`}>
                      {stepTitles[step - 1]}
                    </span>
                  </div>
                ))}
              </div>

              {/* Contact Info */}
              <div className="contact-section">
                <div className="contact-item">
                  <div className="contact-icon">📞</div>
                  <div>
                    <p className="contact-label">¿Necesitas ayuda?</p>
                    <p className="contact-value">+1 (555) 123-4567</p>
                  </div>
                </div>
                <div className="contact-item">
                  <div className="contact-icon">✉️</div>
                  <div>
                    <p className="contact-label">Soporte</p>
                    <p className="contact-value">registro@artisa.com</p>
                  </div>
                </div>
              </div>

              {/* Social Links */}
              <div className="social-section">
                <h3 className="social-title">Síguenos</h3>
                <div className="social-links">
                  <a href="#" className="social-link">📘</a>
                  <a href="#" className="social-link">📷</a>
                  <a href="#" className="social-link">🐦</a>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column */}
          <div className="right-column">
            <div className="form-container">
              {/* Step Header */}
              <div className="step-header">
                <h2 className="step-title">Paso {currentStep}</h2>
                <p className="step-subtitle">{stepTitles[currentStep - 1]}</p>
              </div>

              {msg && (
                <div className="error-alert show">
                  <span className="error-icon">⚠️</span>
                  <span className="error-text">{msg}</span>
                </div>
              )}

              {/* Step 1: User Type */}
              {currentStep === 1 && (
                <div className="step-content">
                  <h3>¿Cómo quieres usar Artisa?</h3>
                  <p>Selecciona el tipo de cuenta que mejor se adapte a ti</p>
                  
                  <div className="radio-group">
                    <div 
                      className={`radio-option ${form.rol === 'comprador' ? 'selected' : ''}`}
                      onClick={() => selectUserType('comprador')}
                    >
                      <div className="radio-button"></div>
                      <div className="radio-content">
                        <div className="radio-title">👤 Comprador</div>
                        <div className="radio-description">Quiero comprar productos artesanales únicos</div>
                      </div>
                    </div>
                    <div 
                      className={`radio-option ${form.rol === 'artesano' ? 'selected' : ''}`}
                      onClick={() => selectUserType('artesano')}
                    >
                      <div className="radio-button"></div>
                      <div className="radio-content">
                        <div className="radio-title">💼 Artesano</div>
                        <div className="radio-description">Quiero vender mis productos artesanales</div>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Step 2: Personal Info */}
              {currentStep === 2 && (
                <div className="step-content">
                  <h3>Información Personal</h3>
                  <p>Cuéntanos un poco sobre ti</p>

                  <div className="grid-2">
                    <div className="form-field">
                      <label className="form-label" htmlFor="nombre">Nombre *</label>
                      <input 
                        type="text" 
                        id="nombre" 
                        name="nombre" 
                        className="form-input" 
                        placeholder="Tu nombre"
                        value={form.nombre}
                        onChange={handleChange}
                      />
                    </div>
                    <div className="form-field">
                      <label className="form-label" htmlFor="apellido">Apellido *</label>
                      <input 
                        type="text" 
                        id="apellido" 
                        name="apellido" 
                        className="form-input" 
                        placeholder="Tu apellido"
                        value={form.apellido}
                        onChange={handleChange}
                      />
                    </div>
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="identificacion">Identificación *</label>
                    <div className="input-group">
                      <span className="input-icon">🆔</span>
                      <input 
                        type="text" 
                        id="identificacion" 
                        name="identificacion" 
                        className="form-input input-with-icon" 
                        placeholder="Número de identificación (solo números)"
                        value={form.identificacion}
                        onChange={handleChange}
                        pattern="[0-9]{8,15}"
                        title="Ingresa solo números (8-15 dígitos)"
                      />
                    </div>
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="correo">Correo Electrónico *</label>
                    <div className="input-group">
                      <span className="input-icon">✉️</span>
                      <input 
                        type="email" 
                        id="correo" 
                        name="correo" 
                        className="form-input input-with-icon" 
                        placeholder="tu@email.com"
                        value={form.correo}
                        onChange={handleChange}
                      />
                    </div>
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="ciudad">Ciudad *</label>
                    <input 
                      type="text" 
                      id="ciudad" 
                      name="ciudad" 
                      className="form-input" 
                      placeholder="Tu ciudad"
                      value={form.ciudad}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="direccion">Dirección</label>
                    <input 
                      type="text" 
                      id="direccion" 
                      name="direccion" 
                      className="form-input" 
                      placeholder="Tu dirección"
                      value={form.direccion}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="pais">País</label>
                    <input 
                      type="text" 
                      id="pais" 
                      name="pais" 
                      className="form-input" 
                      placeholder="Tu país"
                      value={form.pais}
                      onChange={handleChange}
                    />
                  </div>
                </div>
              )}

              {/* Step 3: Additional Details */}
              {currentStep === 3 && (
                <div className="step-content">
                  {form.rol === 'artesano' ? (
                    <div>
                      <h3>Información de Artesano</h3>
                      <p>Cuéntanos sobre tu arte y experiencia</p>

                      <div className="form-field">
                        <label className="form-label" htmlFor="especialidad">Especialidad Artesanal *</label>
                        <select 
                          id="especialidad" 
                          name="especialidad" 
                          className="form-select"
                          value={form.especialidad}
                          onChange={handleChange}
                        >
                          <option value="">¿En qué te especializas?</option>
                          <option value="joyeria">Joyería</option>
                          <option value="ceramica">Cerámica</option>
                          <option value="textiles">Textiles</option>
                          <option value="cuero">Trabajo en Cuero</option>
                          <option value="madera">Trabajo en Madera</option>
                          <option value="otro">Otro</option>
                        </select>
                      </div>

                      <div className="form-field">
                        <label className="form-label" htmlFor="biografia">Cuéntanos tu historia *</label>
                        <textarea 
                          id="biografia" 
                          name="biografia" 
                          className="form-textarea" 
                          placeholder="Comparte tu historia como artesano, tus técnicas, inspiraciones..."
                          value={form.biografia}
                          onChange={handleChange}
                        ></textarea>
                      </div>

                      <div className="form-field">
                        <label className="form-label" htmlFor="historia">Historia adicional</label>
                        <textarea 
                          id="historia" 
                          name="historia" 
                          className="form-textarea" 
                          placeholder="Información adicional sobre tu trabajo artesanal..."
                          value={form.historia}
                          onChange={handleChange}
                        ></textarea>
                      </div>
                    </div>
                  ) : (
                    <div className="success-state">
                      <div className="success-icon">✅</div>
                      <div>
                        <h3 className="success-title">¡Perfecto!</h3>
                        <p className="success-description">
                          Como comprador, ya tienes toda la información necesaria.<br/>
                          Continuemos con la configuración de seguridad.
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              )}

              {/* Step 4: Security */}
              {currentStep === 4 && (
                <div className="step-content">
                  <h3>Configuración de Seguridad</h3>
                  <p>Crea una contraseña segura para tu cuenta</p>

                  <div className="form-field">
                    <label className="form-label" htmlFor="contraseña">Contraseña *</label>
                    <div className="input-group">
                      <input 
                        type="password" 
                        id="contraseña" 
                        name="contraseña" 
                        className="form-input" 
                        placeholder="Mínimo 8 caracteres"
                        value={form.contraseña}
                        onChange={handleChange}
                      />
                    </div>
                  </div>

                  <div className="form-field">
                    <label className="form-label" htmlFor="confirmarContraseña">Confirmar Contraseña *</label>
                    <div className="input-group">
                      <input 
                        type="password" 
                        id="confirmarContraseña" 
                        name="confirmarContraseña" 
                        className="form-input" 
                        placeholder="Repite tu contraseña"
                        value={form.confirmarContraseña}
                        onChange={handleChange}
                      />
                    </div>
                  </div>

                  {form.contraseña && form.confirmarContraseña && form.contraseña !== form.confirmarContraseña && (
                    <div className="error-message">
                      Las contraseñas no coinciden
                    </div>
                  )}
                </div>
              )}

              {/* Step 5: Confirmation */}
              {currentStep === 5 && (
                <div className="step-content">
                  <h3>¡Casi terminamos!</h3>
                  <p>Revisa y acepta nuestros términos</p>

                  {updateSummary()}

                  <div className="checkbox-group">
                    <div className="checkbox-item">
                      <input 
                        type="checkbox" 
                        id="aceptarTerminos" 
                        name="aceptarTerminos" 
                        className="checkbox"
                        checked={form.aceptarTerminos}
                        onChange={handleChange}
                      />
                      <label htmlFor="aceptarTerminos" className="checkbox-label">
                        Acepto los <a href="#" className="checkbox-link">términos y condiciones</a> 
                        y la <a href="#" className="checkbox-link">política de privacidad</a> de Artisa *
                      </label>
                    </div>
                  </div>
                </div>
              )}

              {/* Navigation */}
              <div className="navigation">
                <button 
                  type="button" 
                  className="nav-button nav-button-prev" 
                  onClick={prevStep}
                  disabled={currentStep === 1}
                >
                  ⬅️ Anterior
                </button>
                <button 
                  type="button" 
                  className="nav-button nav-button-next" 
                  onClick={nextStep}
                  disabled={!canProceed() || loading}
                >
                  {loading ? (
                    <>
                      <span className="loading-spinner"></span>
                      Creando cuenta...
                    </>
                  ) : currentStep === totalSteps ? (
                    '✅ ¡Crear Mi Cuenta!'
                  ) : (
                    'Siguiente ➡️'
                  )}
                </button>
              </div>

              {/* Login Link */}
              <div className="login-link">
                <p className="login-text">
                  ¿Ya tienes cuenta? 
                  <Link to="/login" className="login-anchor">¡Inicia sesión aquí!</Link>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Register;
